use grep_matcher::{Captures, Matcher};
use grep_regex::RegexMatcherBuilder;

fn main() {
    let m = RegexMatcherBuilder::new()
        .word(true)
        .line_terminator(Some(b'\n'))
        .build(r"([\w]+[.])*domain[.](\w)+")
        .unwrap();
    for hay in [
        "some.domain.com/x",
        "some.domain.com/x\n",
        "some.domain.com/x\nfoo",
        "some.domain.com\nsome.domain.com/x\nsome.domain.com\n",
    ] {
        for at in 0..hay.len() {
            let r = m
                .find_at(hay.as_bytes(), at)
                .unwrap()
                .map(|mm| (mm.start(), mm.end()));
            let mut caps = m.new_captures().unwrap();
            let c = m.captures_at(hay.as_bytes(), at, &mut caps).unwrap();
            let cr = if c { caps.get(0).map(|mm| (mm.start(), mm.end())) } else { None };
            if r != cr {
                println!("{hay:?} at={at} find={r:?} caps={cr:?}  <-- MISMATCH");
            }
        }
    }
    println!("done");
}

