use grep_regex::RegexMatcherBuilder;
use grep_searcher::{Searcher, Sink, SinkMatch};
use grep_matcher::Captures;

struct Print;
impl Sink for Print {
    type Error = std::io::Error;
    fn matched(&mut self, _s: &Searcher, m: &SinkMatch) -> Result<bool, Self::Error> {
        let bytes = &m.bytes()[m.match_range().clone()];
        println!("match: {:?} offset {:?} line {}", std::str::from_utf8(bytes).unwrap(), m.match_range(), m.line_number().unwrap());
        Ok(true)
    }
}

fn main() {
    let m = RegexMatcherBuilder::new()
        .word(true)
        .line_terminator(Some(b'\n'))
        .build(r"([\w]+[.])*domain[.](\w)+")
        .unwrap();
    let hay = "some.domain.com\nsome.domain.com/x\nsome.domain.com\n";
    let mut s = Searcher::new();
    s.search_slice(&m, hay.as_bytes(), &mut Print).unwrap();
    let _ = <grep_regex::RegexMatcher as grep_matcher::Matcher>::captures;
}

