use grep_matcher::{Captures, Matcher};
use grep_regex::RegexMatcherBuilder;

fn check(m: &grep_regex::RegexMatcher, hay: &str, at: usize, label: &str) {
    let f = m
        .find_at(hay.as_bytes(), at)
        .unwrap()
        .map(|mm| (mm.start(), mm.end()));
    let mut caps = m.new_captures().unwrap();
    let c = m.captures_at(hay.as_bytes(), at, &mut caps).unwrap();
    let cr = if c { caps.get(0).map(|mm| (mm.start(), mm.end())) } else { None };
    if f != cr {
        println!("{label} {hay:?} at={at} find={f:?} caps={cr:?}  <-- MISMATCH");
    }
    // also cross-check with an independent oracle: run captures on each
    // suffix like an iterator would
    let mut pos = at;
    while pos <= hay.len() {
        let f = m
            .find_at(hay.as_bytes(), pos)
            .unwrap()
            .map(|mm| (mm.start(), mm.end()));
        let mut caps = m.new_captures().unwrap();
        let c = m.captures_at(hay.as_bytes(), pos, &mut caps).unwrap();
        let cr = if c { caps.get(0).map(|mm| (mm.start(), mm.end())) } else { None };
        if f != cr {
            println!(
                "{label} {hay:?} iter-at={pos} find={f:?} caps={cr:?}  <-- MISMATCH"
            );
        }
        match f {
            None => break,
            Some((s, e)) => {
                pos = if e > s { e } else { e + 1 };
            }
        }
    }
}

fn main() {
    let pats = [
        r"([\w]+[.])*domain[.](\w)+",
        r"foo",
        r"-2",
        r"\w+",
        r"a|ab",
        r"!foo!",
        r"foo5",
        r"\w*",
        r"!?foo!?",
        r"(?-u)foo[^a]*",
        r"a\x20\n|a\x20",
        r"\w+\W?",
        r"domain[.]\w+",
    ];
    let hays = [
        "some.domain.com\nsome.domain.com/x\nsome.domain.com\n",
        "foo\nfoo\n!foo!\nafoo\nfoo5\n",
        "-2\nx-2y\n--\n-2-2\n",
        "foo\r\nfoo bar\r\nfoo\r\n",
        "aa\nab\nab ab\n\na\n",
        "☃foo☃\nfooб\n!foo!\n",
        "!!foo!!\nfoo!!\n!!foo\na!!foo!!a\n",
        "b  b\nz a y\n  ab  \n",
        "one two three\nfoo bar\n\nword boundary tests here\n",
    ];
    let mut n = 0;
    for word in [true] {
        for crlf in [false, true] {
            for p in pats {
                let m = RegexMatcherBuilder::new()
                    .word(word)
                    .crlf(crlf)
                    .line_terminator(if crlf {
                        Some(grep_matcher::LineTerminator::crlf())
                    } else {
                        None
                    })
                    .build(p)
                    .unwrap();
                for h in hays {
                    for at in 0..h.len() {
                        check(&m, h, at, &format!("[crlf={crlf} {p}]"));
                        n += 1;
                    }
                }
            }
        }
    }
    println!("done, {n} checks");
}

